    if p.is_file() and p.suffix in ['.py','.json','.cpp','.bat','.stdout','.stderr','.map','.asm'] and p.name not in ['update-goals.py','recovery-inventory.json']:
        files.append(p)
files+=list((root/'src').rglob('*.hpp'))+list((root/'src').rglob('*.cpp'))
for p in (root/'review').iterdir():
    if p.is_file() and p.suffix in ['.json','.py'] and p.name!='final-docs-review.json':files.append(p)
for row in state['rows']:
    directory=root/'runs'/row['name']
    for p in directory.iterdir():
        if p.is_file() and p.name not in ['events.csv','owned.etl','owned.diagsession'] and p.suffix not in ['.f32']:
            files.append(p)
    parsed=directory/'parsed-v2'
    if parsed.exists():files.extend(p for p in parsed.iterdir() if p.is_file())
files += [root/'runs/results.json',root/'runs/results-initial.json']
evidence=[];texts={};compressed={}
for p in sorted(set(files)):
    raw=p.read_bytes();digest=hashlib.sha256(raw).hexdigest()
    entry={'path':p.relative_to(root).as_posix(),'bytes':len(raw),'sha256':digest}
    if p.suffix=='.csv':
        assert p.name=='target-samples.csv'
        entry['encoding']='base64(zlib(raw bytes))';compressed.setdefault(digest,base64.b64encode(zlib.compress(raw)).decode('ascii'))
    else:
        text=raw.decode('utf-8');assert text.encode('utf-8')==raw
        entry['encoding']='utf-8';texts.setdefault(digest,text)
    evidence.append(entry)
vectors=[];payloads={}
