#if defined(_WIN32)
#ifndef NOMINMAX
#define NOMINMAX
#endif
#include <windows.h>
#endif
#include "model/arch_qwen.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <thread>

using Clock = std::chrono::steady_clock;
namespace fs = std::filesystem;

int64_t ns(Clock::time_point time) {
    return std::chrono::duration_cast<std::chrono::nanoseconds>(time.time_since_epoch()).count();
}

std::string quote(const std::string& value) {
    std::ostringstream out;
    out << '"';
    for (unsigned char c : value) {
        if (c == '"' || c == '\\') out << '\\' << char(c);
        else if (c < 32) out << "\\u" << std::hex << std::setw(4) << std::setfill('0') << unsigned(c);
        else out << char(c);
    }
    out << '"';
    return out.str();
}

void write_text(const fs::path& path, const std::string& text) {
    std::ofstream out;
    out.exceptions(std::ios::badbit | std::ios::failbit);
    out.open(path, std::ios::binary);
    out << text << '\n';
    out.close();
}

void signal(const fs::path& path, const std::string& text) {
    if (fs::exists(path)) throw std::runtime_error("signal already exists: " + path.string());
    auto temporary = path;
    temporary += ".tmp";
    write_text(temporary, text);
    fs::rename(temporary, path);
}

#if defined(_MSC_VER)
__declspec(noinline)
#else
__attribute__((noinline))
#endif
int64_t wait_for_signal(const fs::path& path) {
    const auto deadline = Clock::now() + std::chrono::seconds(120);
    for (;;) {
        if (fs::exists(path)) {
            if (!fs::is_regular_file(path)) throw std::runtime_error("invalid signal: " + path.string());
            return ns(Clock::now());
        }
        if (Clock::now() >= deadline) throw std::runtime_error("signal timeout: " + path.string());
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
}

uint64_t vector_hash(const std::vector<float>& values) {
    uint64_t hash = 14695981039346656037ull;
    for (float value : values) {
        if (!std::isfinite(value)) throw std::runtime_error("nonfinite output");
        uint32_t bits;
        std::memcpy(&bits, &value, sizeof(bits));
        for (int shift = 0; shift < 32; shift += 8) {
            hash ^= (bits >> shift) & 255;
            hash *= 1099511628211ull;
        }
    }
    return hash;
}

void save_vector(const fs::path& path, const std::vector<float>& values) {
    std::ofstream out;
    out.exceptions(std::ios::badbit | std::ios::failbit);
    out.open(path, std::ios::binary);
    out.write(reinterpret_cast<const char*>(values.data()), std::streamsize(values.size() * sizeof(float)));
    out.close();
}

struct Record {
    int iteration;
    uint32_t pid, caller_tid;
    int64_t pp_start = 0, pp_end = 0, tg_start = 0, tg_end = 0;
    int64_t ready = 0, go = 0, done = 0, release = 0;

    std::string json() const {
        std::ostringstream out;
        out << std::setprecision(17)
            << "{\"iteration\":" << iteration << ",\"pid\":" << pid << ",\"caller_tid\":" << caller_tid
            << ",\"pp_start_ns\":" << pp_start << ",\"pp_end_ns\":" << pp_end
            << ",\"tg_start_ns\":" << tg_start << ",\"tg_end_ns\":" << tg_end
            << ",\"pp_ms\":" << (pp_end - pp_start) / 1e6
            << ",\"tg_ms\":" << (tg_end - tg_start) / 1e6
            << ",\"ready_ns\":" << ready << ",\"go_observed_ns\":" << go
            << ",\"done_ns\":" << done << ",\"release_observed_ns\":" << release << '}';
        return out.str();
    }
};

int main(int argc, char** argv) {
    try {
        if (argc != 4) throw std::runtime_error("usage: harness MODEL TOKENS RUN_DIR");
        uint32_t pid = 0, caller_tid = 0;
#if defined(_WIN32)
        pid = GetCurrentProcessId();
        caller_tid = GetCurrentThreadId();
#else
        throw std::runtime_error("this sampling harness requires Windows");
#endif
        const fs::path directory(argv[3]);
        if (!fs::is_directory(directory)) throw std::runtime_error("run directory must exist");
        for (const char* name : {"ready", "ready.tmp", "go", "done", "done.tmp", "release",
                                 "argv.json", "warmup.f32", "measured.f32", "warmup.json",
                                 "measured.json", "report.json"}) {
            if (fs::exists(directory / name)) throw std::runtime_error(std::string("stale run file: ") + name);
        }
        std::ostringstream arguments;
        arguments << "{\"argv\":[";
        for (int i = 0; i < argc; ++i) {
            if (i) arguments << ',';
            arguments << quote(argv[i]);
        }
        arguments << "],\"pid\":" << pid << ",\"caller_tid\":" << caller_tid
                  << ",\"wait_timeout_seconds\":120,\"wait_sleep_ms\":10}";
        write_text(directory / "argv.json", arguments.str());

        std::ifstream input(argv[2]);
        if (!input) throw std::runtime_error("cannot open token file");
        std::vector<uint32_t> ids;
        std::string word;
        while (input >> word) {
            if (word.empty() || word.find_first_not_of("0123456789") != std::string::npos)
                throw std::runtime_error("invalid token ID");
            auto value = std::stoull(word);
            if (value > UINT32_MAX) throw std::runtime_error("token ID exceeds uint32");
            ids.push_back(uint32_t(value));
        }
        if (!input.eof() || ids.size() != 247) throw std::runtime_error("expected exactly 247 token IDs");
        auto weights = gguf::read_gguf(argv[1]);
        auto cpu = std::make_shared<backend::CpuBackend>();
        infer::Model model(weights, cpu);
        model.set_threads(6);
        model.set_ubatch(128);
        if (cpu->threads_available() != 6) throw std::runtime_error("expected six workers");
        std::vector<uint32_t> prompt(ids.begin(), ids.begin() + 215);
        std::vector<float> warmup_logits;
        uint64_t warmup_hash = 0, measured_hash = 0;
        std::string records[2];
        for (int run = 0; run < 2; ++run) {
            model.reset();
            Record record{run, pid, caller_tid};
            auto start = Clock::now();
            auto logits = model.prefill(prompt);
            const auto pp_end = Clock::now();
            record.pp_start = ns(start);
            record.pp_end = ns(pp_end);
            if (run) {
                if (fs::exists(directory / "go") || fs::exists(directory / "release"))
                    throw std::runtime_error("premature go or release signal");
                record.ready = ns(Clock::now());
                signal(directory / "ready", record.json());
                record.go = wait_for_signal(directory / "go");
                if (fs::exists(directory / "release")) throw std::runtime_error("premature release signal");
            }
            start = Clock::now();
            for (size_t i = 215; i < ids.size(); ++i) logits = model.step(ids[i]);
            const auto tg_end = Clock::now();
            record.tg_start = ns(start);
            record.tg_end = ns(tg_end);
            if (run) {
                if (fs::exists(directory / "release")) {
                    save_vector(directory / "measured.f32", logits);
                    write_text(directory / "measured.json", record.json());
                    throw std::runtime_error("release signal preceded done");
                }
                record.done = ns(Clock::now());
                signal(directory / "done", record.json());
                try {
                    record.release = wait_for_signal(directory / "release");
                } catch (...) {
                    save_vector(directory / "measured.f32", logits);
                    write_text(directory / "measured.json", record.json());
                    throw;
                }
            }
            const char* name = run ? "measured" : "warmup";
            save_vector(directory / (std::string(name) + ".f32"), logits);
            records[run] = record.json();
            write_text(directory / (std::string(name) + ".json"), records[run]);
            const auto hash = vector_hash(logits);
            if (!run) {
                warmup_hash = hash;
                warmup_logits = logits;
            } else {
                measured_hash = hash;
                if (hash != warmup_hash || logits.size() != warmup_logits.size() ||
                    std::memcmp(logits.data(), warmup_logits.data(), logits.size() * sizeof(float)))
                    throw std::runtime_error("warmup/measured vector mismatch");
            }
        }
        std::ostringstream report;
        report << "{\"status\":\"pass\",\"pid\":" << pid << ",\"caller_tid\":" << caller_tid
               << ",\"threads\":6,\"ubatch\":128,\"prompt\":215,\"forced_decode\":32,"
               << "\"warmup_vector_fnv64\":\"" << std::hex << warmup_hash
               << "\",\"final_vector_fnv64\":\"" << measured_hash << std::dec
               << "\",\"records\":[" << records[0] << ',' << records[1] << "]}";
        write_text(directory / "report.json", report.str());
        std::cout << report.str() << '\n';
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}

